#!/usr/bin/env node/** * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ *  BANF Bosonto Utsob 2026 ΓÇö Full Test Runner v3.0 * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ * *  Comprehensive test for ALL pipeline members: *    Γ£à Pipeline: All 16 members processed, emails ΓåÆ ranadhir *    Γ£à Response Attribution: ranadhir's replies attributed to original member *    Γ£à Family Guard: Only Ranadhir's family data can be updated via response *    Γ£à Signup Flow: Member signup tested for each ORIGINAL member (not ranadhir) *    Γ£à Security Questions: Set and verify for each member *    Γ£à Forgot Password: Full flow tested *    Γ£à Forgot Username: Lookup by phone/name tested * *  Usage:  node bosonto-test-runner.js *  Output: bosonto-test-dashboard.html * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */const fs = require('fs');const path = require('path');const crypto = require('crypto');// ΓöÇΓöÇ Configuration ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst CONFIG = {  TEST_MODE: true,  TEST_EMAIL: 'ranadhir.ghosh@gmail.com',  BANF_EMAIL: 'banfjax@gmail.com',  EVENT_NAME: 'Bosonto Utsob 2026',  EVENT_DATE: 'Saturday, March 7, 2026',  PAYMENT_DEADLINE: 'April 30, 2026',  EARLY_BIRD_DEADLINE: 'March 31, 2026',  MEMBERSHIP_YEAR: '2026-27',  ZELLE_EMAIL: 'banfjax@gmail.com',  MEMBERSHIP_URL: 'https://banfwix.wixsite.com/banf1/_functions/membership_register',  SIGNIN_URL: 'https://banfwix.wixsite.com/banf1/_functions/signin',  FORGOT_URL: 'https://banfwix.wixsite.com/banf1/_functions/forgot_password'};// ΓöÇΓöÇ Embed membership images as base64 for email ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇlet IMG_EVENTS_B64 = '';let IMG_FEES_B64 = '';try {  IMG_EVENTS_B64 = fs.readFileSync(path.join(__dirname, 'membership_events.jpg')).toString('base64');  IMG_FEES_B64 = fs.readFileSync(path.join(__dirname, 'membership_fees.jpg')).toString('base64');  console.log('≡ƒô╕ Embedded membership_events.jpg (' + Math.round(IMG_EVENTS_B64.length / 1024) + ' KB b64)');  console.log('≡ƒô╕ Embedded membership_fees.jpg (' + Math.round(IMG_FEES_B64.length / 1024) + ' KB b64)');} catch (e) {  console.warn('ΓÜá∩╕Å  Could not load membership images:', e.message);}const PRICING = {  m2_eb:    { family: 375, couple: 290, individual: 215, student: 145, name: 'M2 Premium Early Bird', desc: 'All 17 events + priority seating + cultural workshops' },  m2:       { family: 410, couple: 330, individual: 240, student: 165, name: 'M2 Premium',            desc: 'All 17 events + priority seating + cultural workshops' },  m1:       { family: 280, couple: 255, individual: 140, student: 100, name: 'M1 Regular',            desc: '4 included events + add-on options for others' },  cultural: { family: 180, couple: 140, individual: 100, student:  75, name: 'Cultural Special',      desc: 'Cultural events focus' },  guest:    { family:  50, couple:  35, individual:  25, student:  15, name: 'Guest Pass',            desc: 'Per-event entry' }};const SPOUSE_OVERRIDES = {  'ranadhir.ghosh@gmail.com': { spouseName: 'Moumita Mukherjee (Ghosh)', spouseEmail: 'moumita.mukherje@gmail.com' }};const SECURITY_QUESTIONS = [  "What is your mother's maiden name?",  "What city were you born in?",  "What is the name of your first pet?",  "What is your favorite food?",  "What school did you attend as a child?",  "What is your father's middle name?"];// ΓöÇΓöÇ Recommendation Engine ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// Determines the best membership tier for a member based on:// 1. Household type from evite (family/couple/individual)// 2. Previous year membership data// 3. Default: M2 Premium Early Bird is ALWAYS the preferred recommendationfunction buildRecommendation(m) {  const tier = m.membershipTier; // family | couple | individual  const prevYear = m.previousYear;  const rec = {    preferred: 'm2_eb',    preferredPrice: PRICING.m2_eb[tier],    regularPrice: PRICING.m2[tier],    tier: tier,    prevCategory: null,    prevAmount: null,    prevTier: null,    reasoning: '',    savings: PRICING.m2[tier] - PRICING.m2_eb[tier],    allOptions: []  };  // Previous year context  if (prevYear) {    rec.prevCategory = prevYear.category;    rec.prevAmount = prevYear.amount;    rec.prevTier = tier;    // If prev year was M2/Premium, keep recommending M2 EB    if (prevYear.category && (prevYear.category.toLowerCase().includes('m2') || prevYear.category.toLowerCase().includes('premium'))) {      rec.reasoning = `You had ${prevYear.category} ($${prevYear.amount}) last year. The M2 Premium Early Bird at $${rec.preferredPrice} gives you the same premium access at a discount!`;    } else if (prevYear.category && prevYear.category.toLowerCase().includes('m1')) {      rec.reasoning = `You had ${prevYear.category} ($${prevYear.amount}) last year. We recommend upgrading to M2 Premium Early Bird at $${rec.preferredPrice} for full access to all 17 events!`;    } else {      rec.reasoning = `Based on your ${capitalize(tier)} membership, we recommend M2 Premium Early Bird at $${rec.preferredPrice} for the best value.`;    }  } else {    rec.reasoning = `As a ${capitalize(tier)} member, M2 Premium Early Bird at $${rec.preferredPrice} gives you full access to all 17 events at the best price!`;  }  // Build all options for the member's tier  for (const [catId, cat] of Object.entries(PRICING)) {    if (catId === 'guest') continue;    rec.allOptions.push({      id: catId, name: cat.name, price: cat[tier], desc: cat.desc,      isPreferred: catId === 'm2_eb',      isRegular: catId === 'm2'    });  }  return rec;}const STAGES = [  { id: 'email_scan',     name: 'Email Scan',     icon: '≡ƒôº' },  { id: 'evite_analysis', name: 'Evite Analysis',  icon: '≡ƒô¿' },  { id: 'wf_payment_scan',name: 'Payment Scan',    icon: '≡ƒÅª' },  { id: 'membership_rec', name: 'Membership',      icon: '≡ƒÄ½' },  { id: 'payment_match',  name: 'Price Match',     icon: '≡ƒöì' },  { id: 'payment',        name: 'Payment',         icon: '≡ƒÆ░' },  { id: 'comm_verify',    name: 'Contact Verify',  icon: '≡ƒôï' },  { id: 'member_signup',  name: 'Member Signup',   icon: '≡ƒöÉ' },  { id: 'event_mgmt',     name: 'Event Mgmt',      icon: '≡ƒÄë' }];// ΓöÇΓöÇ Load CRM Data ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst recon = JSON.parse(fs.readFileSync(path.join(__dirname, 'banf-crm-reconciliation.json'), 'utf8'));const allMembers = recon.members || [];console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ');console.log('  ≡ƒî╕ BANF Bosonto Utsob 2026 ΓÇö Full Test Runner v3.0');console.log('  ≡ƒº¬ TEST MODE: All emails ΓåÆ ' + CONFIG.TEST_EMAIL);console.log('  ≡ƒöÉ Tests: Pipeline + Response + Signup + Security + Recovery');console.log('ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ\n');// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// FAMILY / SPOUSE DETECTION (same as v2)// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction detectFamily(m) {  const result = { spouseName: null, spouseEmail: null, childrenCount: m.inferredKids || 0, familyLabel: null, confidence: 'none', allMembers: [] };  const emailKey = (m.email || '').toLowerCase();  if (SPOUSE_OVERRIDES[emailKey]) { const ov = SPOUSE_OVERRIDES[emailKey]; result.spouseName = ov.spouseName; result.spouseEmail = ov.spouseEmail; result.confidence = 'confirmed'; result.allMembers.push({ name: ov.spouseName, relationship: 'spouse', email: ov.spouseEmail }); }  if (!result.spouseName && (m.householdMembers || []).length > 0) { const hm = m.householdMembers[0]; result.spouseName = hm.displayName || `${hm.firstName} ${hm.lastName}`.trim(); result.spouseEmail = hm.email; result.confidence = 'high'; result.allMembers.push({ name: result.spouseName, relationship: 'spouse', email: hm.email }); }  if (!result.spouseName && m.householdDisplayName) { const match = m.householdDisplayName.match(/^(.+?)\s*&\s*(.+)/); if (match) { const memberFirst = (m.firstName || '').toLowerCase(); const spouse = match[1].toLowerCase().includes(memberFirst) ? match[2].trim() : match[1].trim(); if (spouse) { result.spouseName = spouse; result.confidence = 'medium'; result.allMembers.push({ name: spouse, relationship: 'spouse', email: null }); } } }  if (!result.spouseName) { for (const pay of (m.paymentRecords || [])) { if (!pay.rawName) continue; const slashMatch = pay.rawName.match(/^(.+?)\s*(?:Da\s*)?\/\s*(.+?)(?:\s*Di)?$/i); if (slashMatch) { const n1 = slashMatch[1].replace(/\s*Da\s*$/i, '').trim(); const n2 = slashMatch[2].replace(/\s*Di\s*$/i, '').trim(); const memberFirst = (m.firstName || '').toLowerCase(); const spouse = n1.toLowerCase().includes(memberFirst) ? n2 : n1; if (spouse && spouse.length > 1) { result.spouseName = spouse; result.confidence = 'medium'; result.allMembers.push({ name: spouse, relationship: 'spouse', email: null }); break; } } } }  for (const fm of (m.familyMembers || [])) { if (!result.allMembers.some(x => x.email === fm.email || x.name === fm.displayName)) result.allMembers.push({ name: fm.displayName, relationship: 'family member', email: fm.email }); }  if (result.spouseName && m.householdType === 'family') { const kids = result.childrenCount; result.familyLabel = `${m.firstName} & ${result.spouseName.split(' ')[0]} ${m.lastName} Family${kids > 0 ? ` (+${kids} child${kids > 1 ? 'ren' : ''})` : ''}`; }  else if (result.spouseName && m.householdType === 'couple') { result.familyLabel = `${m.firstName} & ${result.spouseName.split(' ')[0]} ${m.lastName}`; }  else { result.familyLabel = m.displayName; }  return result;}function getPreviousYearAmount(m) {  const hhAmt = m.householdMembershipAmount;  const prevPay = (m.paymentRecords || []).find(p => p.year === '2025-26');  if (hhAmt && hhAmt > 0) return { amount: hhAmt, category: m.householdMembershipCategory || 'Previous Plan', source: 'household_record' };  if (prevPay) { const kh = { 170: 340, 150: 300, 107.5: 215, 125: 250 }; return { amount: kh[prevPay.amount] || prevPay.amount, category: prevPay.category, source: kh[prevPay.amount] ? 'corrected_halved' : 'payment_record' }; }  return null;}function guessCategoryFromAmount(amount, hhType) {  const tier = hhType === 'family' ? 'family' : hhType === 'couple' ? 'couple' : 'individual';  for (const [catId, cat] of Object.entries(PRICING)) { if (cat[tier] === amount) return catId; }  for (const [catId, cat] of Object.entries(PRICING)) { for (const [t, p] of Object.entries(cat)) { if (t !== 'name' && t !== 'desc' && p === amount) return catId; } }  return null;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// AUTH SIMULATION ΓÇö Password hash, security Q&A, sessions// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction hashPassword(password, salt) {  const combined = salt + ':' + password + ':BANF-SECRET-2025';  let hash = 5381;  for (let i = 0; i < combined.length; i++) { hash = ((hash << 5) + hash) + combined.charCodeAt(i); hash |= 0; }  return (hash >>> 0).toString(36) + '_' + Buffer.from(salt + password.length).toString('base64').replace(/=/g, '');}function generateSalt() { const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'; let s = ''; for (let i = 0; i < 16; i++) s += chars[Math.floor(Math.random() * chars.length)]; return s; }function verifyPassword(password, salt, expectedHash) { return hashPassword(password, salt) === expectedHash; }function generateSessionToken(email) { const ts = Date.now().toString(36); const chars = 'abcdefghijklmnopqrstuvwxyz0123456789'; let rand = ''; for (let i = 0; i < 20; i++) rand += chars[Math.floor(Math.random() * chars.length)]; return `ST-${ts}-${rand}`; }function generateRegCode(firstName, lastName, type = 'NM') {  const initials = ((firstName||'X')[0] + (lastName||'X')[0]).toUpperCase();  const d = new Date(); const ds = `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; let rand = ''; for (let i = 0; i < 4; i++) rand += chars[Math.floor(Math.random() * chars.length)];  return `BANF-${type}-${initials}${ds}-${rand}`;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// RESPONSE ATTRIBUTION ΓÇö ranadhir's te